cat > src/election.js <<'EOF'
const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

function fail(msg) {
  const e = new Error(msg)
  e.userError = true
  throw e
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    const err = (m) => fail(`error: line ${n}: ${m}`)
    if (t[0] === 'candidates') {
      if (candidates !== null || ballots.length > 0) err('candidates must be declared once, before any ballot')
      if (t.length < 2) err('expected candidates <name>...')
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) err(`invalid candidate name ${name}`)
        if (seen.has(name)) err(`candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
    } else if (t[0] === 'ballot') {
      if (candidates === null) err('candidates must be declared once, before any ballot')
      if (t.length < 3) err('expected ballot <count> <candidate>...')
      if (!COUNT.test(t[1])) err('count must be a positive integer')
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) err(`unknown candidate ${name}`)
        if (seen.has(name)) err(`candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: Number(t[1]), prefs: t.slice(2) })
    } else {
      err(`unknown directive ${t[0]}`)
    }
  })
  if (candidates === null) fail('error: no candidates')
  return { candidates, ballots }
}

export function count({ candidates, ballots }, mode) {
  const continuing = new Set(candidates)
  const history = []
  const out = []
  let winner = null
  for (let k = 1; ; k++) {
    const votes = new Map([...continuing].map((c) => [c, 0]))
    let active = 0
    let total = 0
    for (const b of ballots) {
      total += b.count
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) { votes.set(c, votes.get(c) + b.count); active += b.count }
    }
    history.push(votes)
    const listed = [...votes].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    let line = `round ${k}: ` + listed.map(([c, v]) => `${c}=${v}`).join(' ') + ` exhausted=${total - active}`
    out.push(line)
    if (active === 0) break
    const top = listed.find(([, v]) => v * 2 > active)
    if (top) { winner = top[0]; break }
    let s = [...continuing]
    for (let r = 0; r < history.length && s.length > 1;) {
      const vals = s.map((c) => history[r].get(c))
      const min = Math.min(...vals)
      if (vals.every((v) => v === min)) { r++; continue }
      s = s.filter((c) => history[r].get(c) === min)
      r = 0
    }
    const elim = s.reduce((a, b) => (b > a ? b : a))
    continuing.delete(elim)
    out.push(`eliminated ${elim}`)
  }
  const end = winner === null ? 'no winner' : `winner ${winner}`
  if (mode === 'tally') return `rounds ${history.length}\n${end}\n`
  return out.join('\n') + '\n' + end + '\n'
}
EOF
