  const a = parseAddr(word)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${word.toUpperCase()}`)
  const k = keyOf(a.c, a.r)
  if (cells.has(k)) fail(`error: line ${i + 1}: cell ${nameOf(k)} is declared twice`)
  cells.set(k, content)
