{"file_path":"src/parse.js","content":"import { parseAddr, colName } from './addr.js'

function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    if (/[0-9]/.test(c)) {
      let m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i))
      toks.push({ t: 'num', v: Number(m[0]) })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      const m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i))
      toks.push({ t: 'word', v: m[0] })
      i += m[0].length
      continue
    }
    const two = src.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') {
      toks.push({ t: 'op', v: two })
      i += 2
      continue
    }
    if ('^*/+-=<>(),:'.includes(c)) {
      toks.push({ t: 'op', v: c })
      i++
      continue
    }
    return null
  }
  return toks
}

export function rangeCells(a, b) {
  const out = []
  const c1 = Math.min(a.col, b.col), c2 = Math.max(a.col, b.col)
  const r1 = Math.min(a.row, b.row), r2 = Math.max(a.row, b.row)
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push({ col: c, row: r, key: colName(c) + r })
  return out
}

class Fail extends Error {}

export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return { ok: false, refs: [] }
  let pos = 0
  let misplaced = 0
  const refs = []
  const isOp = (v) => pos < toks.length && toks[pos].t === 'op' && toks[pos].v === v
  const expect = (v) => { if (!isOp(v)) throw new Fail(); pos++ }

  function cmp() {
    let l = add()
    while (pos < toks.length && toks[pos].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[pos].v)) {
      const op = toks[pos++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[pos++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[pos++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) {
      pos++
      return { type: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[pos++].v
      return { type: 'neg', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (pos >= toks.length) throw new Fail()
    const t = toks[pos]
    if (t.t === 'num') { pos++; return { type: 'num', v: t.v } }
    if (isOp('(')) {
      pos++
      const e = cmp()
      expect(')')
      return { type: 'paren', e }
    }
    if (t.t === 'word') {
      pos++
      if (isOp('(')) {
        pos++
        const args = []
        if (!isOp(')')) {
          for (;;) {
            const e = cmp()
            if (e.type === 'range') misplaced--
            args.push(e)
            if (isOp(',')) { pos++; continue }
            break
          }
        }
        expect(')')
        return { type: 'call', name: t.v.toUpperCase(), args }
      }
      const up = t.v.toUpperCase()
      if (isOp(':') && pos + 1 < toks.length && toks[pos + 1].t === 'word') {
        pos++
        const w2 = toks[pos++].v
        const a = parseAddr(t.v)
        const b = parseAddr(w2)
        misplaced++
        if (a && b) {
          const cells = rangeCells(a, b)
          for (const c of cells) refs.push(c)
          return { type: 'range', cells }
        }
        return { type: 'range', cells: null }
      }
      if (up === 'TRUE') return { type: 'bool', v: true }
      if (up === 'FALSE') return { type: 'bool', v: false }
      const a = parseAddr(t.v)
      if (a) { refs.push(a); return { type: 'ref', key: a.key } }
      return { type: 'badref' }
    }
    throw new Fail()
  }

  let ast
  try {
    ast = cmp()
    if (pos !== toks.length) throw new Fail()
  } catch (e) {
    if (e instanceof Fail) return { ok: false, refs: [] }
    throw e
  }
  return { ok: true, ast, refs, bad: misplaced > 0 }
}
"}

{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'

const num = (v) => ({ t: 'n', v })
const err = (v) => ({ t: 'e', v })
const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export function formatValue(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}

function finite(v) {
  return v.t === 'n' && !Number.isFinite(v.v) ? err('#DIV/0!') : v
}

function cmpStr(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'n') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 's') return cmpStr(a.v, b.v)
  return Number(a.v) - Number(b.v)
}

const ARITY = { SUM: [1, Infinity], MIN: [1, Infinity], MAX: [1, Infinity], COUNT: [1, Infinity], AVG: [1, Infinity], ABS: [1, 1], IF: [3, 3] }

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.stack = new Set()
  }

  valueOf(key) {
    const c = this.cells.get(key)
    if (!c) return num(0)
    if (this.memo.has(key)) return this.memo.get(key)
    if (this.stack.has(key)) return err('#CYCLE!')
    this.stack.add(key)
    let v
    try { v = this.compute(c.content) } finally { this.stack.delete(key) }
    this.memo.set(key, v)
    return v
  }

  compute(s) {
    if (s[0] === '=') {
      const p = parseFormula(s.slice(1))
      if (!p.ok || p.bad) return err('#ERR!')
      return this.ev(p.ast)
    }
    if (s === '') return num(0)
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
    if (ERRS.includes(s)) return err(s)
    return { t: 's', v: s }
  }

  // Values an argument contributes.
  argValues(a) {
    if (a.type === 'range') {
      if (!a.cells) return [err('#REF!')]
      return a.cells.map((c) => this.valueOf(c.key))
    }
    return [this.ev(a)]
  }

  scalar(a) {
    const vs = this.argValues(a)
    const e = vs.find((v) => v.t === 'e')
    if (e) return e
    return vs.length === 1 ? vs[0] : err('#VALUE!')
  }

  ev(n) {
    switch (n.type) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'badref': return err('#REF!')
      case 'ref': return this.valueOf(n.key)
      case 'paren': return this.ev(n.e)
      case 'range': return err('#ERR!')
      case 'neg': {
        const v = toNum(this.ev(n.e))
        if (v.t === 'e') return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l0 = this.ev(n.l)
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      if (l0.t === 'e') return l0
      const r0 = this.ev(n.r)
      if (r0.t === 'e') return r0
      const d = compare(l0, r0)
      const r = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
      return { t: 'b', v: r }
    }
    const l = toNum(l0)
    if (l.t === 'e') return l
    const r = toNum(this.ev(n.r))
    if (r.t === 'e') return r
    const a = l.v, b = r.v
    switch (n.op) {
      case '+': return finite(num(a + b))
      case '-': return finite(num(a - b))
      case '*': return finite(num(a * b))
      case '/': return b === 0 ? err('#DIV/0!') : finite(num(a / b))
      case '^': {
        const v = Math.pow(a, b)
        return Number.isFinite(v) ? num(v) : err('#DIV/0!')
      }
    }
    return err('#ERR!')
  }

  call(n) {
    const spec = ARITY[n.name]
    if (!spec) return err('#NAME?')
    const k = n.args.length
    if (k < spec[0] || k > spec[1]) return err('#ERR!')
    if (n.name === 'IF') {
      const c = toNum(this.scalar(n.args[0]))
      if (c.t === 'e') return c
      return this.scalar(n.args[c.v !== 0 ? 1 : 2])
    }
    if (n.name === 'ABS') {
      const v = toNum(this.scalar(n.args[0]))
      return v.t === 'e' ? v : num(Math.abs(v.v))
    }
    const vals = []
    for (const a of n.args) for (const v of this.argValues(a)) vals.push(v)
    const e = vals.find((v) => v.t === 'e')
    if (e) return e
    if (n.name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.t === 'e') return x
      nums.push(x.v)
    }
    switch (n.name) {
      case 'SUM': return finite(num(nums.reduce((a, b) => a + b, 0)))
      case 'MIN': return num(Math.min(...nums))
      case 'MAX': return num(Math.max(...nums))
      case 'AVG': return finite(num(nums.reduce((a, b) => a + b, 0) / nums.length))
    }
    return err('#ERR!')
  }
}
"}

