const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export function formatValue(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}

function finite(v) {
  return v.t === 'n' && !Number.isFinite(v.v) ? err('#DIV/0!') : v
}

function cmpStr(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'n') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 's') return cmpStr(a.v, b.v)
  return Number(a.v) - Number(b.v)
}

const ARITY = { SUM: [1, Infinity], MIN: [1, Infinity], MAX: [1, Infinity], COUNT: [1, Infinity], AVG: [1, Infinity], ABS: [1, 1], IF: [3, 3] }

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.stack = new Set()
  }

  valueOf(key) {
    const c = this.cells.get(key)
    if (!c) return num(0)
    if (this.memo.has(key)) return this.memo.get(key)
    if (this.stack.has(key)) return err('#CYCLE!')
    this.stack.add(key)
    let v
    try { v = this.compute(c.content) } finally { this.stack.delete(key) }
    this.memo.set(key, v)
    return v
  }

  compute(s) {
    if (s[0] === '=') {
      const p = parseFormula(s.slice(1))
      if (!p.ok || p.bad) return err('#ERR!')
      return this.ev(p.ast)
    }
    if (s === '') return num(0)
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
    if (ERRS.includes(s)) return err(s)
    return { t: 's', v: s }
  }

  // Values an argument contributes.
  argValues(a) {
    if (a.type === 'range') {
      if (!a.cells) return [err('#REF!')]
      return a.cells.map((c) => this.valueOf(c.key))
    }
    return [this.ev(a)]
  }

  scalar(a) {
    const vs = this.argValues(a)
    const e = vs.find((v) => v.t === 'e')
    if (e) return e
    return vs.length === 1 ? vs[0] : err('#VALUE!')
  }

  ev(n) {
    switch (n.type) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'badref': return err('#REF!')
      case 'ref': return this.valueOf(n.key)
      case 'paren': return this.ev(n.e)
      case 'range': return err('#ERR!')
      case 'neg': {
        const v = toNum(this.ev(n.e))
        if (v.t === 'e') return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l0 = this.ev(n.l)
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      if (l0.t === 'e') return l0
      const r0 = this.ev(n.r)
      if (r0.t === 'e') return r0
      const d = compare(l0, r0)
      const r = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
      return { t: 'b', v: r }
    }
    const l = toNum(l0)
    if (l.t === 'e') return l
    const r = toNum(this.ev(n.r))
    if (r.t === 'e') return r
    const a = l.v, b = r.v
    switch (n.op) {
      case '+': return finite(num(a + b))
      case '-': return finite(num(a - b))
      case '*': return finite(num(a * b))
      case '/': return b === 0 ? err('#DIV/0!') : finite(num(a / b))
      case '^': {
        const v = Math.pow(a, b)
        return Number.isFinite(v) ? num(v) : err('#DIV/0!')
      }
    }
    return err('#ERR!')
  }

  call(n) {
    const spec = ARITY[n.name]
    if (!spec) return err('#NAME?')
    const k = n.args.length
    if (k < spec[0] || k > spec[1]) return err('#ERR!')
    if (n.name === 'IF') {
      const c = toNum(this.scalar(n.args[0]))
      if (c.t === 'e') return c
      return this.scalar(n.args[c.v !== 0 ? 1 : 2])
    }
    if (n.name === 'ABS') {
      const v = toNum(this.scalar(n.args[0]))
      return v.t === 'e' ? v : num(Math.abs(v.v))
    }
    const vals = []
    for (const a of n.args) for (const v of this.argValues(a)) vals.push(v)
    const e = vals.find((v) => v.t === 'e')
    if (e) return e
    if (n.name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.t === 'e') return x
      nums.push(x.v)
    }
    switch (n.name) {
      case 'SUM': return finite(num(nums.reduce((a, b) => a + b, 0)))
      case 'MIN': return num(Math.min(...nums))
      case 'MAX': return num(Math.max(...nums))
      case 'AVG': return finite(num(nums.reduce((a, b) => a + b, 0) / nums.length))
    }
    return err('#ERR!')
  }
}
"}

