{"file_path":"src/cli.js","content":"#!/usr/bin/env node
import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { Evaluator, formatValue } from './eval.js'
import { parseAddr, compareKeys } from './addr.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  fail('error: usage: cli.js values|deps')
}
const mode = args[0]

const text = readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const word = /^[^ \t]*/.exec(s)[0]
  const rest = s.slice(word.length).replace(/^[ \t]+/, '')
  const a = parseAddr(word)
  if (!a) fail(`error: line ${n}: invalid cell address ${word}`)
  if (cells.has(a.key)) fail(`error: line ${n}: cell ${a.key} is declared twice`)
  cells.set(a.key, { addr: a, content: rest })
}

const keys = [...cells.keys()].sort(compareKeys)
const out = []
if (mode === 'values') {
  const ev = new Evaluator(cells)
  for (const k of keys) out.push(`${k}=${formatValue(ev.valueOf(k))}`)
} else {
  for (const k of keys) {
    const c = cells.get(k).content
    let line = `${k}:`
    if (c[0] === '=') {
      const p = parseFormula(c.slice(1))
      if (p.ok) {
        const set = new Set(p.refs.map((r) => r.key))
        for (const r of [...set].sort(compareKeys)) line += ' ' + r
      }
    }
    out.push(line)
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
"}

