    else {
      const i = inp.indexOf('/', inp[0] === '/' ? 1 : 0)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
export class PctError extends Error {}

function pct(s, name) {
  if (s === undefined) return s
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new PctError(name)
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const ch = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(ch) ? ch : '%' + h.toUpperCase()
  })
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const DEFAULTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

// Check order: path, userinfo, host, query, fragment.
export function normalize(u) {
  const scheme = u.scheme === undefined ? undefined : lower(u.scheme)
  let userinfo, host, port, hasAuth = u.authority !== undefined
