  }
  path = removeDots(path)
  if (hasAuth && path === '') path = '/'
  out += path
  if (query !== undefined) out += '?' + query
  if (fragment !== undefined) out += '#' + fragment
  return out
}

export function resolve(base, ref) {
  const r = parse(ref)
  let t
  if (r.scheme !== undefined) t = { ...r, path: removeDots(r.path) }
  else if (r.authority !== undefined) t = { ...r, scheme: base.scheme, path: removeDots(r.path) }
  else if (r.path === '') {
    t = { scheme: base.scheme, authority: base.authority, path: base.path,
