        if (e === '"') out += '"'; else if (e === '\\') out += '\\'
        else if (e === 'n') out += '\n'; else if (e === 't') out += '\t'
        else if (e === 'r') out += '\r'; else if (e === '0') out += '\0'
        else if (e === 'u') {
          const h = this.s.slice(this.i, this.i + 4)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16)); this.i += 4
        } else fail('invalid escape \\' + String.fromCodePoint(e.codePointAt(0)) .replace(/^$/, e))
      } else out += c
    }
  }
  name() {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.str()
    let j = this.i
    while (j < this.s.length && bare.test(this.s[j])) j++
    if (j === this.i) fail('expected a name')
    const r = this.s.slice(this.i, j); this.i = j; return r
  }
  dotted() {
    const r = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] === '.') { this.i++; this.ws(); r.push(this.name()) } else { this.i = save; return r }
    }
  }
  value(path) {
    const c = this.s[this.i]
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.str() }
    if (c === '[') {
      this.i++
      const items = []
      for (;;) {
        this.ws()
        if (this.s[this.i] === ']') { this.i++; break }
        items.push(this.value(path + '[' + items.length + ']'))
        this.ws()
        const d = this.s[this.i]
        if (d === ',') this.i++
        else if (d === ']') { this.i++; break }
        else fail('unterminated array')
      }
      return { t: 'array', items, aot: false }
    }
    if (c === '{') {
      this.i++
      const tb = mkTable()
      this.ws()
      if (this.s[this.i] === '}') { this.i++; return tb }
      for (;;) {
        this.ws()
        const k = this.dotted()
        this.ws()
        if (this.s[this.i] !== '=') fail('expected = in an inline table')
        this.i++; this.ws()
        const base = path ? path + '.' : ''
        const names = k
        // value path is the full key path
        const v = this.value(base + names.join('.'))
        assign(tb, path, k, v)
        this.ws()
        const d = this.s[this.i]
        if (d === ',') this.i++
        else if (d === '}') { this.i++; return tb }
        else fail('unterminated inline table')
      }
    }
    let j = this.i
    while (j < this.s.length && !isWs(this.s[j]) && !',]}'.includes(this.s[j])) j++
    const w = this.s.slice(this.i, j); this.i = j
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    const I = '[+-]?\\d+(?:_\\d+)*'
    if (new RegExp('^' + I + '$').test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    if (new RegExp('^' + I + '(?:\\.\\d+(?:_\\d+)*(?:[eE][+-]?\\d+(?:_\\d+)*)?|[eE][+-]?\\d+(?:_\\d+)*)$').test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }
}

const join = (p, k) => (p ? p + '.' : '') + k

// walk names (all but last) from table `cur`; returns [table, pathOfParent]
function walk(cur, base, names) {
  let path = base
  for (const n of names) {
    path = join(path, n)
    let nx = cur.map.get(n)
    if (!nx) { nx = mkTable(); cur.map.set(n, nx) }
    if (nx.t === 'array' && nx.aot) nx = nx.items[nx.items.length - 1]
    else if (nx.t !== 'table') fail(path + ' is not a table')
    cur = nx
  }
  return [cur, path]
}

function assign(cur, base, names, v) {
  const [tb, p] = walk(cur, base, names.slice(0, -1))
  const last = names[names.length - 1]
  if (tb.map.has(last)) fail('key ' + join(p, last) + ' is defined twice')
  tb.map.set(last, v)
}

function parse(text) {
  const root = mkTable()
  let cur = root, curPath = ''
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  lines.forEach((line, idx) => {
    try {
      const p = new P(line)
      p.ws()
      const c = line[p.i]
      if (c === undefined || c === '#' || c === ';') return
      if (c === '[') {
        const aot = line[p.i + 1] === '['
        p.i += aot ? 2 : 1
        p.ws()
        const names = p.dotted()
        p.ws()
        const close = aot ? ']]' : ']'
        if (line.slice(p.i, p.i + close.length) !== close) fail('unterminated table header')
        p.i += close.length
        p.ws()
        if (!p.eol()) fail('trailing text after a table header')
        const [tb, path] = walk(root, '', names.slice(0, -1))
        const last = names[names.length - 1]
        const full = join(path, last)
        let ex = tb.map.get(last)
        if (aot) {
          if (!ex) { ex = { t: 'array', items: [], aot: true }; tb.map.set(last, ex) }
          else if (ex.t !== 'array' || !ex.aot) fail(full + ' is not an array of tables')
          const nt = mkTable(); ex.items.push(nt); cur = nt
        } else {
          if (!ex) { ex = mkTable(); tb.map.set(last, ex) }
          else if (ex.t !== 'table') fail(full + ' is not a table')
          else if (ex.hdr) fail('table ' + full + ' is defined twice')
          ex.hdr = true; cur = ex
        }
        curPath = full
        return
      }
      const names = p.dotted()
      p.ws()
      if (line[p.i] !== '=') fail('expected key = value')
      p.i++; p.ws()
      const v = p.value(join(curPath, names.join('.')))
      p.ws()
      if (!p.eol()) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    } catch (e) {
      if (e instanceof Fail) e.message = 'line ' + (idx + 1) + ': ' + e.message
      throw e
    }
  })
  return root
}

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = [...n.map.keys()].sort(cmp)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.map.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function keys(n, path, out) {
  if (n.t === 'table') {
    for (const k of [...n.map.keys()].sort(cmp)) {
      const c = n.map.get(k), p = join(path, k)
      out.push(p + ' ' + c.t); keys(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => { const p = path + '[' + i + ']'; out.push(p + ' ' + c.t); keys(c, p, out) })
  }
}

const args = process.argv.slice(2)
