import { readFileSync } from 'node:fs'

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }
  const mode = args[0]
  let text = readFileSync(0, 'utf8')
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null

  const num = (v, field, least) => {
    if (!UINT.test(v) || BigInt(v) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
    return BigInt(v)
  }

  try {
    lines.forEach((raw, i) => {
      const n = i + 1
      const line = raw.trim()
      if (line === '' || line.startsWith('#')) return
      const f = line.split(/\s+/)
      const fail = (m) => { throw Object.assign(new Fail(`line ${n}: ${m}`)) }
      try {
        const d = f[0]
        if (d === 'bucket' || d === 'window') {
          const want = d === 'bucket' ? 5 : 4
          if (f.length !== want) throw new Fail(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
          if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
          let p
          if (d === 'bucket') {
            const capacity = num(f[2], 'capacity', 1)
            const refill = num(f[3], 'refill', 0)
            const per = num(f[4], 'per', 1)
            p = { kind: 'bucket', name: f[1], capacity, refill, per }
          } else {
            const limit = num(f[2], 'limit', 0)
            const span = num(f[3], 'span', 1)
            p = { kind: 'window', name: f[1], limit, span }
          }
          if (events.length) throw new Fail('declarations must come before the first event')
          if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
          policies.set(f[1], p)
        } else if (d === 'route') {
          if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
          if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
          if (events.length) throw new Fail('declarations must come before the first event')
          if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
          const list = []
          for (const pn of f.slice(2)) {
            if (!policies.has(pn)) throw new Fail(`unknown policy ${pn}`)
            list.push(policies.get(pn))
          }
          routes.set(f[1], list)
        } else if (d === 'event') {
          if (f.length !== 3) throw new Fail('expected event <tick> <key>')
          const tick = num(f[1], 'tick', 0)
          if (!NAME.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
          if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
          lastTick = tick
          events.push({ tick, key: f[2] })
        } else {
          throw new Fail(`unknown directive ${d}`)
        }
      } catch (e) {
        if (e instanceof Fail) fail(e.message)
        throw e
      }
    })
  } catch (e) {
    if (e instanceof Fail) {
      process.stderr.write(`error: ${e.message}\n`)
      process.exit(2)
    }
    throw e
  }

  const states = new Map() // policyName\0key -> state
  const stateOf = (p, key, tick) => {
    const id = p.name + '\0' + key
    let s = states.get(id)
    if (!s) {
      s = p.kind === 'bucket' ? { scaled: p.capacity * p.per, last: tick } : { ticks: [] }
      states.set(id, s)
    }
    return s
  }
  const advance = (p, s, tick) => {
    if (p.kind === 'bucket') {
      const cap = p.capacity * p.per
      s.scaled += p.refill * (tick - s.last)
      if (s.scaled > cap) s.scaled = cap
      s.last = tick
    } else {
      const cut = tick - p.span
      let k = 0
      while (k < s.ticks.length && s.ticks[k] <= cut) k++
      if (k) s.ticks.splice(0, k)
    }
  }
  const allows = (p, s) => p.kind === 'bucket' ? s.scaled >= p.per : BigInt(s.ticks.length) < p.limit
  const record = (p, s, tick) => {
    if (p.kind === 'bucket') s.scaled -= p.per
    else s.ticks.push(tick)
  }

  const out = []
  const per = new Map()
  let ta = 0, td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const [pre, list] of routes) {
      if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    }
    let denier = null
    if (best !== null) {
      const list = routes.get(best)
      const ss = list.map((p) => {
        const s = stateOf(p, key, tick)
        advance(p, s, tick)
        return s
      })
      for (let i = 0; i < list.length; i++) {
        if (!allows(list[i], ss[i])) { denier = list[i]; break }
      }
      if (!denier) list.forEach((p, i) => record(p, ss[i], tick))
    }
    const c = per.get(key) || { a: 0, d: 0 }
    per.set(key, c)
    if (denier) { c.d++; td++; out.push(`${tick} ${key} deny ${denier.name}`) }
    else { c.a++; ta++; out.push(`${tick} ${key} allow`) }
  }
  if (mode === 'summary') {
    out.length = 0
    for (const k of [...per.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
      out.push(`${k} allowed=${per.get(k).a} denied=${per.get(k).d}`)
    }
    out.push(`total allowed=${ta} denied=${td}`)
  }
  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
}

main()
