{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(pos, reason) {
    super(reason)
    this.pos = pos
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdent = (c) => isLetter(c) || isDigit(c) || c === '_'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const line = new Array(n + 1)
  const col = new Array(n + 1)
  let l = 1
  let c = 1
  for (let i = 0; i < n; i++) {
    line[i] = l
    col[i] = c
    if (cs[i] === '\n') { l++; c = 1 }
    else if (cs[i] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  line[n] = l
  col[n] = c
  const at = (i) => ({ line: line[i], col: col[i] })
  const tokens = []
  let i = 0

  const digits = (pred) => {
    // consumes a run of digits with single underscores between digits; assumes cs[i] is a digit
    i++
    for (;;) {
      if (pred(cs[i])) i++
      else if (cs[i] === '_' && pred(cs[i + 1])) i += 2
      else break
    }
  }

  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; i += 2 }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; i += 2 }
        else i++
      }
      if (depth > 0) throw new ScanError(at(start), 'unterminated block comment')
      continue
    }
    const start = i
    const pos = at(start)
    if (ch === 'r' && cs[i + 1] === '"') {
      i += 2
      let s = ''
      while (i < n && cs[i] !== '"') s += cs[i++]
      if (i >= n) throw new ScanError(pos, 'unterminated string')
      i++
      tokens.push({ pos, kind: 'rawstring', body: JSON.stringify(s) })
      continue
    }
    if (isLetter(ch) || ch === '_') {
      while (isIdent(cs[i])) i++
      const s = cs.slice(start, i).join('')
      tokens.push({ pos, kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
      continue
    }
    if (isDigit(ch)) {
      const p = cs[i + 1]
      let bad = false
      const radix = ch === '0' ? { x: isHex, b: isBin, o: isOct }[(p || '').toLowerCase()] : undefined
      if (radix) {
        i += 2
        if (radix(cs[i])) digits(radix)
        else bad = true
      } else {
        digits(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { i++; digits(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) { i++; digits(isDigit) }
          else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { i += 2; digits(isDigit) }
        }
      }
      if (isIdent(cs[i])) {
        bad = true
        while (isIdent(cs[i])) i++
      }
      const s = cs.slice(start, i).join('')
      if (bad) throw new ScanError(pos, `invalid number ${s}`)
      tokens.push({ pos, kind: 'number', body: s })
      continue
    }
    if (ch === '"') {
      i++
      let s = ''
      for (;;) {
        if (i >= n) throw new ScanError(pos, 'unterminated string')
        const d = cs[i]
        if (d === '"') { i++; break }
        if (d === '\n') throw new ScanError(at(i), 'newline in string')
        if (d !== '\\') { s += d; i++; continue }
        const bs = i
        const e = cs[i + 1]
        if (e === undefined) throw new ScanError(pos, 'unterminated string')
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) { s += simple[e]; i += 2; continue }
        if (e === 'x') {
          if (isHex(cs[i + 2]) && isHex(cs[i + 3])) {
            s += String.fromCharCode(parseInt(cs[i + 2] + cs[i + 3], 16))
            i += 4
            continue
          }
        } else if (e === 'u' && cs[i + 2] === '{') {
          let j = i + 3
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (h.length > 0 && cs[j] === '}' && parseInt(h, 16) <= 0x10ffff) {
            s += String.fromCodePoint(parseInt(h, 16))
            i = j + 1
            continue
          }
        }
        throw new ScanError(at(bs), `invalid escape \\${e}`)
      }
      tokens.push({ pos, kind: 'string', body: JSON.stringify(s) })
      continue
    }
    const two = ch + (cs[i + 1] || '')
    if (PUNCT2.includes(two)) {
      i += 2
      tokens.push({ pos, kind: 'punct', body: two })
      continue
    }
    if (PUNCT1.includes(ch)) {
      i++
      tokens.push({ pos, kind: 'punct', body: ch })
      continue
    }
    throw new ScanError(pos, `unexpected character ${ch}`)
  }
  return tokens
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const text = readFileSync(0).toString('utf8')
  let tokens
  try {
    tokens = scan(text)
  } catch (e) {
    if (!(e instanceof ScanError)) throw e
    process.stderr.write(`error: ${e.pos.line}:${e.pos.col}: ${e.message}\n`)
    process.exit(2)
  }
  let out = ''
  if (args[0] === 'tokens') {
    for (const t of tokens) out += `${t.pos.line}:${t.pos.col} ${t.kind} ${t.body}\n`
  } else {
    for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
}

main()
