export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  lines.forEach((line, idx) => {
    try {
      const p = new LineParser(line)
      p.skipWs()
      const c = p.peek()
      if (c === undefined || c === '#' || c === ';') return
      if (c === '[') {
        const isArr = line[p.i + 1] === '['
        p.i += isArr ? 2 : 1
        p.skipWs()
        const names = p.dotted()
        p.skipWs()
        if (p.peek() !== ']') fail('unterminated table header')
        p.i++
        if (isArr) {
          if (p.peek() !== ']') fail('unterminated table header')
          p.i++
        }
        p.skipWs()
        if (!p.atEnd()) fail('trailing text after a table header')
        const parent = walk(root, names.slice(0, -1), [])
        const last = names[names.length - 1]
        const path = names.join('.')
        const ex = parent.map.get(last)
        if (isArr) {
          if (!ex) {
            const t = newTable()
            parent.map.set(last, { kind: 'array', aot: true, items: [t] })
            cur = t
          } else if (ex.kind === 'array' && ex.aot) {
            const t = newTable()
            ex.items.push(t)
            cur = t
          } else fail(`${path} is not an array of tables`)
        } else if (!ex) {
          const t = newTable()
          t.headerDefined = true
          parent.map.set(last, t)
          cur = t
        } else if (ex.kind !== 'table') {
          fail(`${path} is not a table`)
        } else {
          if (ex.headerDefined) fail(`table ${path} is defined twice`)
          ex.headerDefined = true
          cur = ex
        }
        curPath = names
        return
      }
      p.pair(cur, curPath, 'top')
      p.skipWs()
      if (!p.atEnd()) fail('trailing text after a value')
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${idx + 1}: ${e.tomlMessage}`)
      throw e
    }
  })
